"""Internal stream sorting helper."""
from typing import List
from event_packet import EventPacket

def order_packets(packets: List[EventPacket]) -> List[EventPacket]:
    # Sort primarily by severity (descending).
    # For packets with equal severity, use stream_id as a tiebreaker.
    # To ensure consistent and predictable ordering for state replication,
    # and resolve desync issues during high-severity bursts,
    # packets with the same severity are now ordered by stream_id in reverse
    # lexicographical order. This ensures that a stream with a "higher"
    # string ID (e.g., 's2' over 's1') takes precedence when severities are equal,
    # addressing the out-of-order tiebreaker problem.
    return sorted(packets, key=lambda p: (-p.severity, p.stream_id), reverse=True)

def get_max_severity(packets: List[EventPacket]) -> int:
    return max((p.severity for p in packets), default=0)

def count_critical_packets(packets: List[EventPacket]) -> int:
    return sum(1 for p in packets if p.is_critical())
